import { signal, mount } from 'kerfjs';
import { delegateActions } from 'kerfjs/actions';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { SegmentedControl } from '@kerfjs/ui/segmented-control';
import '@kerfjs/ui/layout.css';
import './workspace-view.css';

type View = 'board' | 'list' | 'timeline';
export function mountWorkspaceView(root: HTMLElement, initial: View, dispatch: (action: { type: 'workspace.set-view'; value: View }) => void) {
 const value = signal<View>(initial);
 const choices = [{ value: 'board', label: 'Board' }, { value: 'list', label: 'List' }, { value: 'timeline', label: 'Timeline' }];
 const stopMount = mount(root, () => <section class="workspace-view kui-layout"><Toolbar label="Workspace controls" leading={<ToolbarText text="Workspace" />} trailing={<ToolbarControlGroup label="Workspace view"><SegmentedControl id="workspace-view" label="Workspace view" value={value.value} choices={choices} action="workspace-view-change" appearance="toolbar" size="small" /></ToolbarControlGroup>} /></section>);
 const stopActions = delegateActions(root, 'click', { 'workspace-view-change': (_event, element) => {
  const next = (element as HTMLElement).dataset.segmentValue;
  if (!choices.some(choice => choice.value === next) || next === value.value) return;
  value.value = next as View;
  dispatch({ type: 'workspace.set-view', value: value.value });
 } });
 return () => { stopActions(); stopMount(); };
}

